import{_ as o,o as P,c as p,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const r=JSON.parse('{"title":"第一章 PSPP 概述","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/01-第一章-PSPP概述.md","filePath":"tutorial/01-第一章-PSPP概述.md","lastUpdated":1785684581000}'),s={name:"tutorial/01-第一章-PSPP概述.md"};function c(t,e,d,i,S,l){return P(),p("div",null,[...e[0]||(e[0]=[a(`<h1 id="第一章-pspp-概述" tabindex="-1">第一章 PSPP 概述 <a class="header-anchor" href="#第一章-pspp-概述" aria-label="Permalink to &quot;第一章 PSPP 概述&quot;">​</a></h1><h2 id="_1-1-什么是-pspp" tabindex="-1">1.1 什么是 PSPP <a class="header-anchor" href="#_1-1-什么是-pspp" aria-label="Permalink to &quot;1.1 什么是 PSPP&quot;">​</a></h2><p>PSPP 是一套自由、开源的统计分析与报表生成程序，由 GNU 项目维护。它的设计目标，是提供一套与 SPSS 这类商业统计产品句法相近、却完全不受专有许可约束的分析工具——既能在图形界面里点选完成常规分析，也能通过纯文本命令写出可复现的批处理脚本。</p><p>PSPP 以两种形态交付，二者共享同一套计算内核：</p><ul><li><code>pspp</code>：命令行界面（文本界面）。分析者把命令写入语法文件，再以 <code>pspp file.sps</code> 的方式批量运行，或者进入交互提示符逐条键入。</li><li><code>psppire</code>：图形用户界面（Graphical User Interface，PSPPIRE）。它提供数据编辑器、语法编辑器与输出查看器，使不熟悉命令的分析者也能通过菜单完成操作。</li></ul><p>在 <code>pspp</code> 命令行界面中，既可以把分析写成语法文件后批量运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pspp analysis.sps</span></span></code></pre></div><p>也可以进入交互提示符逐条键入（每行一条命令，以英文句点结尾）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PSPP&gt; DESCRIPTIVES /VARIABLES=height.</span></span></code></pre></div><p>而在 <code>psppire</code> 图形界面下，同样的分析可在语法编辑器里输入 <code>DESCRIPTIVES /VARIABLES=height.</code> 后，通过 Run 菜单运行【手册明示】。</p><p>需要强调：PSPP 的语法与 SPSS 的语法&quot;相似&quot;（similar to SPSS statistical products），而非逐字兼容。大部分常用命令、子命令的写法彼此相通，但在细节与过程覆盖面上存在差别，这一点将在 1.3 节展开。分析结果可输出为多种格式，包括 ASCII、PostScript、PDF、HTML、DocBook 与 TeX，便于直接嵌入论文、网页或排版系统。</p><h2 id="_1-2-pspp-的发展与开源背景" tabindex="-1">1.2 PSPP 的发展与开源背景 <a class="header-anchor" href="#_1-2-pspp-的发展与开源背景" aria-label="Permalink to &quot;1.2 PSPP 的发展与开源背景&quot;">​</a></h2><p>PSPP 诞生于自由软件运动的脉络之中。它隶属于 GNU 项目，践行&quot;自由软件&quot;（free software）的理念：用户不仅免费获得程序，更享有运行、研究、再分发与改进它的四项核心自由。这一理念决定了 PSPP 与商业统计软件在授权上的根本不同——后者的能力被密封在许可证条款之内，而 PSPP 的全部权利从一开始就交还给使用者。</p><p>程序本身以 GNU 通用公共许可证（GNU GPL）发布；随附文档则以 GNU 自由文档许可证（GFDL，GNU Free Documentation License）发布。换言之，你运行的每一行可执行代码与阅读的每一份手册文字，其许可都是公开、可核查的，而非包裹在最终用户许可协议（EULA）的封闭条款里。这种许可结构使本书得以在遵循原许可的前提下进行中文整理与表述。</p><p>自由软件并不意味着&quot;已经做完&quot;。PSPP 官方手册原话即坦言：&quot;PSPP is a work in progress.&quot;（PSPP 仍是一项进行中的工作。）这句话不是谦辞，而是对软件状态的如实陈述：它持续改进，亦有尚未补齐的环节。读者在依赖 PSPP 完成关键分析时，应参照官方手册与自身专业判断，而非假定它已与某一商业产品完全对等。</p><h2 id="_1-3-pspp-与-spss-的关系及异同" tabindex="-1">1.3 PSPP 与 SPSS 的关系及异同 <a class="header-anchor" href="#_1-3-pspp-与-spss-的关系及异同" aria-label="Permalink to &quot;1.3 PSPP 与 SPSS 的关系及异同&quot;">​</a></h2><p>把 PSPP 理解为&quot;SPSS 的开源克隆&quot;是一个常见的误会。两者确实渊源深厚：PSPP 的许多命令名、子命令结构乃至数据文件格式（<code>.sav</code>）都刻意贴近 SPSS，使习惯 SPSS 的分析者能平滑迁移。语法层面的&quot;相似&quot;是真实的，也是 PSPP 最有价值的特性之一。</p><p>然而相似不等于完整兼容，二者之间存在清晰边界。其一，PSPP 并未实现 SPSS 的全部过程，尤其是一批高级统计与作图功能目前缺失（详见 1.4 节与附录）。其二，PSPP 解读语法时遵循自己的实现，某些在 SPSS 中可行的写法未必被 PSPP 接受，反过来 PSPP 的扩展也未必能在 SPSS 中运行。其三，图形界面 PSPPIRE 的菜单布局参照了通用统计软件习惯，但并未逐一复刻 SPSS 的每一个对话框，相关路径在本书中均标注为界面推断。</p><p>因此，从 SPSS 迁移到 PSPP 通常是低成本的，尤其当工作集中在描述统计、t 检验、相关、回归与常规方差分析时；而当流程依赖尚未实现的高级过程（如析因方差分析的 <code>UNIANOVA</code>、基于 GPL 的原始作图）时，则需要寻找替代路径或保留原有软件。认清这条边界，既能避免在不兼容命令上反复碰壁，也能在可行范围内充分享受开源方案带来的自由。</p><h2 id="_1-4-pspp-的功能特点与适用场景" tabindex="-1">1.4 PSPP 的功能特点与适用场景 <a class="header-anchor" href="#_1-4-pspp-的功能特点与适用场景" aria-label="Permalink to &quot;1.4 PSPP 的功能特点与适用场景&quot;">​</a></h2><p>PSPP 的强项，在于把统计分析变得透明、可复现且零成本。它适合以下几类场景：</p><ul><li><strong>教学与入门</strong>：命令与菜单一一对应，便于讲解每一项统计量背后的计算逻辑，又不像商业软件那样带来授权负担。</li><li><strong>中小规模数据分析</strong>：问卷、实验记录、观测样本等常规体量下，PSPP 的描述统计、假设检验、方差分析与回归能力足以覆盖绝大多数课程与研究需求。</li><li><strong>可复现的语法批处理</strong>：把分析写成 <code>.sps</code> 语法文件，既能在 <code>pspp</code> 命令行批量重跑，也便于在服务器、容器等无图形界面的环境中复用，保证结果可审计、可追溯。</li><li><strong>多格式输出</strong>：分析产物可导出为 PDF、HTML、TeX 等，方便嵌入报告、网页与论文排版系统。</li></ul><p>也必须正视它的局限。PSPP 当前不支持以下部分高级过程（手册第 21 章 Not Implemented 清单）：</p><ul><li><code>ANOVA</code> 与 <code>UNIANOVA</code>（析因方差分析）：双因素及以上的方差分析在 PSPP 中须改用 <code>GLM</code> 命令，并在 <code>/DESIGN</code> 子命令中显式写出交互项（如 <code>age_group*sex</code>）。单因素方差分析仍可用 <code>ONEWAY</code>。</li><li><code>GGRAPH</code>、<code>IGRAPH</code>、<code>XGRAPH</code>（基于 GPL 的原始自定义作图）：PSPP 当前不支持，无法用 GPL 语言绘制任意图形；常规统计图应改用 <code>GRAPH</code> 或 <code>FREQUENCIES</code>/<code>EXAMINE</code>/<code>CROSSTABS</code> 内嵌的图形子命令。</li><li><code>STEMLEAF</code>（茎叶图）：PSPP 当前不支持；若需观察分布形态，可改用 <code>FREQUENCIES /HISTOGRAM</code> 或 <code>EXAMINE /PLOT=HISTOGRAM</code> 生成直方图替代。</li><li><code>GET TRANSLATE</code>：PSPP 当前不支持；导入 Excel 或 CSV 应改用 <code>GET DATA /TYPE=ODS</code> 或 <code>GET DATA /TYPE=TXT</code>。</li><li>另有 <code>MANOVA</code>、<code>MULT RESPONSE</code>、<code>CURVEFIT</code>、<code>PPLOT</code> 等过程亦未实现。</li></ul><p>这些缺口不影响 PSPP 在主流教学与中小规模分析中的可用性，但要求使用者清楚边界、及时转向可行方案，而非在缺失命令上反复碰壁。</p><h2 id="_1-5-本书约定与符号说明" tabindex="-1">1.5 本书约定与符号说明 <a class="header-anchor" href="#_1-5-本书约定与符号说明" aria-label="Permalink to &quot;1.5 本书约定与符号说明&quot;">​</a></h2><p>为使后续各章口径一致，本书（技术侧）作如下约定：</p><p>命令、子命令、变量名、文件扩展名与英文菜单项一律保持英文原样，例如 <code>COMPUTE</code>、<code>/VARIABLES</code>、<code>psppire</code>、<code>.sav</code>，其后中文为说明。凡涉及图形界面的菜单路径，若属界面推断（即依据通用统计软件界面给出、手册未逐项文档化），均在附近标注&quot;（界面推断，手册未逐项文档化）&quot;，提示读者以实际软件为准。</p><p>代码示例使用围栏代码块呈现，保留英文原样。PSPP 命令以英文句点 <code>.</code> 结尾；在交互提示符（如 <code>PSPP&gt;</code>）下一行一条键入时，句点同样需要；而在某些特定提示符（如 <code>data&gt;</code>）录入数据期间，则不要再重复输入句点。行内代码用反引号包裹。</p><p>统计符号采用通行约定：显著性水平记为 α，概率值记为 p，样本均值记为 x̄，样本标准差记为 s。其余统计量在正文首次出现时一并说明，避免读者来回翻查。</p><p>下面用一个轻量示例验证安装是否就绪：在终端运行 <code>pspp --version</code> 查看版本信息，或在图形界面中启动 <code>psppire</code>（界面推断，手册未逐项文档化）观察窗口是否正常弹出。两者任一成功，即表明 PSPP 已安装可用。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pspp --version</span></span>
<span class="line"><span>pspp (GNU PSPP) 2.0.1-gff8d3d</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>启动 PSPPIRE 后，典型窗口由数据编辑器、语法编辑器（File → New → Syntax）与输出查看器组成；若窗口出现并能新建语法文件，便可进入后续章节的数据管理练习。本书随附示例所用的 <code>physiology.sav</code>、<code>personnel.sav</code>、<code>repairs.sav</code>、<code>horticulture.sav</code> 等数据均来自手册自带的示例集，纯属虚构，仅用于演示操作步骤，不得用于任何真实研究结论。</p>`,33)])])}const u=o(s,[["render",c]]);export{r as __pageData,u as default};
